import re

def parse_action(text: str):
    m = re.search(r"Action:\s*(\w+)\[(.*?)\]", text, re.DOTALL)
    if not m:
        return None, None
    return m.group(1), m.group(2).strip()   # (tool_name, tool_input)

tool, arg = parse_action("Thought: look it up\nAction: search[France]")
# tool='search', arg='France' -> now run TOOLS[tool](arg)

