import re

def parse_action(text):
    m = re.search(r"Action:\s*(\w+)\[(.*?)\]", text)
    return (m.group(1), m.group(2)) if m else (None, None)

TOOLS = {"search": lambda q: "France population is 68 million"}

# a fake model: returns the next Thought+Action given the transcript
script = [
    "Thought: I need France's population.\nAction: search[population of France]",
    "Thought: I have the number now.\nAction: finish[About 68 million.]",
]

transcript = ""
for turn in script:
    tool, arg = parse_action(turn)
    print(turn)
    if tool == "finish":
        print("ANSWER:", arg)
        break
    obs = TOOLS[tool](arg)
    print("Observation:", obs)
    transcript += turn + "\nObservation: " + obs + "\n"
